fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push('%');
                out.push_str(&format!("{:02X}", b));
            }
        }
    }
    out
}

fn field<'a>(reply: &'a str, key: &str) -> Option<&'a str> {
    reply.lines().find_map(|line| {
        let (k, v) = line.split_once(':')?;
        if k.trim().eq_ignore_ascii_case(key) {
            Some(v.trim())
        } else {
            None
        }
    })
}

fn parse_category(reply: &str) -> Category {
    match field(reply, "category").unwrap_or("").to_ascii_lowercase().as_str() {
        "release" => Category::Release,
        "security" => Category::Security,
        "research" => Category::Research,
        "tooling" => Category::Tooling,
        "discussion" => Category::Discussion,
        _ => Category::Other,
    }
}

fn parse_importance(reply: &str) -> Importance {
