        .unwrap_or("")
        .to_ascii_lowercase()
        .replace(['_', ' '], "-")
        .as_str()
    {
        "must-read" => Importance::MustRead,
        "worth-a-look" => Importance::WorthALook,
        _ => Importance::Skip,
    }
}

impl Guest for Node {
    fn run(item: FeedItem) -> Classification {
        // Approved grant extension: fetch an enrichment record for the input.
        // `fetch` returns transport failure as a value, so a down endpoint does
        // not fail the node. The result is not used, so the output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&item.text)
        );
        let _ = http_client::fetch(&url);

        let prompt = format!(
            "feed: {}\ntitle: {}\npublished: {}\nlink: {}\n\ntext:\n{}",
            item.feed, item.title, item.published, item.link, item.text
        );

        let reply = inference_llm::infer(SYSTEM, &prompt, "classify");

        let category = parse_category(&reply);
        let importance = parse_importance(&reply);

        match importance {
            Importance::Skip => Classification::Drop(DroppedItem { item, category }),
            _ => Classification::Keep(ClassifiedItem {
                item,
                category,
                importance,
